\copy (WITH unmapped AS (SELECT lm.id AS law_id, lm.law_name FROM public.law_master lm LEFT JOIN public.law_sector_mapping lsm ON lsm.law_id=lm.id WHERE lsm.id IS NULL AND lm.is_active=true) SELECT u.law_id, u.law_name, la.article_no, la.article_title, left(regexp_replace(la.article_text, '\s+', ' ', 'g'), 300) AS article_text_head FROM unmapped u JOIN public.law_article la ON la.law_id = u.law_id WHERE (la.article_no IN ('1','2','3') OR la.article_title ILIKE '%목적%' OR la.article_title ILIKE '%적용%' OR la.article_title ILIKE '%정의%' OR la.article_title ILIKE '%대상%' OR la.article_text ILIKE '%이 법은%' OR la.article_text ILIKE '%이 규칙은%' OR la.article_text ILIKE '%이 고시는%' OR la.article_text ILIKE '%적용한다%') ORDER BY u.law_name, la.article_no) TO 'coverage_evidence.csv' WITH CSV HEADER
